/// `ConfigOptions.lua:979-987` `repeatMode`
fn a979_repeat_mode(v: &LV, c: &mut ApplyCtx<'_>) -> LuaResult<()> {
    if leq(v, &ls("AVERAGE")) {
        nmod(c.mod_list, "Condition:averageRepeat", ModType::Flag, Value::Bool(true), Some("Config"), vec![]);
        nmod(c.mod_list, "MinionModifier", ModType::List, Value::table(table(&[("mod", cmod("Condition:averageRepeat", ModType::Flag, Value::Bool(true), Some("Config"), vec![]))])), None, vec![]);
    } else if leq(v, &ls("FINAL")) || leq(v, &ls("FINAL_DPS")) {
        nmod(c.mod_list, "Condition:alwaysFinalRepeat", ModType::Flag, Value::Bool(true), Some("Config"), vec![]);
        nmod(c.mod_list, "MinionModifier", ModType::List, Value::table(table(&[("mod", cmod("Condition:alwaysFinalRepeat", ModType::Flag, Value::Bool(true), Some("Config"), vec![]))])), None, vec![]);
    }
    Ok(())
}

